def run(context):
    # Assume context.symbol_scores is a list of dictionaries with 'symbol' and 'score'.
    ranked = sorted(context['symbol_scores'], key=lambda x: x['score'], reverse=True)
    return {'ranked_symbols': [s['symbol'] for s in ranked[:10]]}

def run(context):
    analysis = {}
    for symbol, avg_return, targets, stops in context['inputs']:
        analysis[symbol] = {
            'performance': 'winner' if avg_return > 0 else 'loser',
            'suggestions': 'Review strategy' if stops > targets else 'Continue'
        }
    return analysis
